from __future__ import annotations

import argparse
import csv
import json
from pathlib import Path
from typing import Sequence

import torch
from transformers import AutoConfig, AutoModel, AutoTokenizer


DEFAULT_MODEL_NAME = str(
    Path(__file__).resolve().parent / "models" / "matbert-base-cased"
)


def load_description_csv(
    input_path: str | Path,
    id_column: str = "cif_id",
    text_column: str = "description",
) -> tuple[list[str], list[str]]:
    """Load structure descriptions generated by transfer_to_text.py."""
    input_path = Path(input_path)
    ids: list[str] = []
    texts: list[str] = []

    with input_path.open(newline="", encoding="utf-8") as csv_file:
        reader = csv.DictReader(csv_file)
        if reader.fieldnames is None:
            raise ValueError(f"{input_path} is empty or is not a valid CSV file")

        missing_columns = {
            column for column in (id_column, text_column)
            if column not in reader.fieldnames
        }
        if missing_columns:
            raise ValueError(
                f"{input_path} is missing columns: "
                f"{', '.join(sorted(missing_columns))}"
            )

        for row in reader:
            text = (row.get(text_column) or "").strip()
            if not text:
                continue
            ids.append((row.get(id_column) or "").strip())
            texts.append(text)

    if not texts:
        raise ValueError(f"No descriptions found in {input_path}")

    return ids, texts


def resolve_device(device: str = "auto") -> torch.device:
    if device == "auto":
        return torch.device("cuda" if torch.cuda.is_available() else "cpu")
    return torch.device(device)


def embed_texts(
    texts: Sequence[str],
    model_name: str = DEFAULT_MODEL_NAME,
    batch_size: int = 16,
    max_length: int = 512,
    device: str = "auto",
) -> torch.Tensor:
    """Encode each text with MatBERT and return CLS embeddings on CPU."""
    if batch_size <= 0:
        raise ValueError("batch_size must be greater than 0")
    if not texts:
        raise ValueError("texts cannot be empty")

    torch_device = resolve_device(device)
    tokenizer = AutoTokenizer.from_pretrained(model_name)
    config = AutoConfig.from_pretrained(model_name)
    model_kwargs = {"add_pooling_layer": False} if config.model_type == "bert" else {}
    model = AutoModel.from_pretrained(model_name, **model_kwargs).to(torch_device)
    model.eval()

    embeddings: list[torch.Tensor] = []
    with torch.no_grad():
        for start in range(0, len(texts), batch_size):
            batch_texts = list(texts[start:start + batch_size])
            inputs = tokenizer(
                batch_texts,
                return_tensors="pt",
                truncation=True,
                padding=True,
                max_length=max_length,
            )
            inputs = {
                key: value.to(torch_device)
                for key, value in inputs.items()
            }
            outputs = model(**inputs)
            cls_embedding = outputs.last_hidden_state[:, 0, :].detach().cpu()
            embeddings.append(cls_embedding)

    return torch.cat(embeddings, dim=0)


def embed_description_csv(
    input_path: str | Path,
    output_path: str | Path,
    model_name: str = DEFAULT_MODEL_NAME,
    batch_size: int = 16,
    max_length: int = 512,
    device: str = "auto",
    include_text: bool = False,
) -> dict[str, object]:
    ids, texts = load_description_csv(input_path)
    embeddings = embed_texts(
        texts,
        model_name=model_name,
        batch_size=batch_size,
        max_length=max_length,
        device=device,
    )

    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)

    # The training loader performs ID-based lookup. Keeping IDs as dictionary
    # keys prevents silent graph-text reordering when graph caches are reused.
    payload: dict[str, object] = {}
    for sample_id, text, embedding in zip(ids, texts, embeddings):
        record: dict[str, object] = {"embedding": embedding}
        if include_text:
            record["description"] = text
        payload[str(sample_id)] = record

    torch.save(payload, output_path)
    metadata_path = output_path.with_suffix(output_path.suffix + ".metadata.json")
    metadata_path.write_text(
        json.dumps(
            {
                "format": "id_to_record",
                "embedding_key": "embedding",
                "num_texts": len(texts),
                "embedding_dim": int(embeddings.shape[-1]),
                "model_name": model_name,
                "source": str(Path(input_path)),
                "max_length": max_length,
            },
            indent=2,
        ),
        encoding="utf-8",
    )
    return {
        "output_path": output_path,
        "metadata_path": metadata_path,
        "num_texts": len(texts),
        "embedding_shape": tuple(embeddings.shape),
        "device": str(resolve_device(device)),
    }


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Embed crystal structure descriptions with MatBERT."
    )
    parser.add_argument("input", help="CSV file generated by transfer_to_text.py")
    parser.add_argument(
        "-o",
        "--output",
        default="outputs/matbert_embeddings.pt",
        help="Path to save the embedding tensor payload",
    )
    parser.add_argument(
        "--model-name",
        default=DEFAULT_MODEL_NAME,
        help="Hugging Face model name or local model path",
    )
    parser.add_argument("--batch-size", type=int, default=16)
    parser.add_argument("--max-length", type=int, default=512)
    parser.add_argument(
        "--device",
        default="auto",
        help="auto, cpu, cuda, or a specific device such as cuda:0",
    )
    parser.add_argument(
        "--include-text",
        action="store_true",
        help="Store descriptions in the output .pt file as well",
    )
    return parser


def main() -> None:
    args = build_parser().parse_args()
    result = embed_description_csv(
        args.input,
        args.output,
        model_name=args.model_name,
        batch_size=args.batch_size,
        max_length=args.max_length,
        device=args.device,
        include_text=args.include_text,
    )
    print(
        "Saved {num_texts} embeddings to {output_path} "
        "with shape {embedding_shape} on {device}".format(**result)
    )


if __name__ == "__main__":
    main()
